--------------------------------------------------------------------------------
-- fir_tb_pkg.vhd
-- Shared types, constants for fir_filter OSVVM testbench.
-- C_COEFFS must match the DUT generated by dsp_gen.py.
--------------------------------------------------------------------------------
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

package fir_tb_pkg is

  constant C_DATA_WIDTH  : positive := 16;
  constant C_COEFF_WIDTH : positive := 16;
  constant C_TAPS        : positive := 8;
  constant C_ACC_WIDTH   : positive := 32;

  subtype data_t  is signed(C_DATA_WIDTH-1 downto 0);
  subtype coeff_t is signed(C_COEFF_WIDTH-1 downto 0);
  subtype acc_t   is signed(C_ACC_WIDTH-1 downto 0);

  type data_vec_t  is array (natural range <>) of data_t;
  type coeff_vec_t is array (0 to C_TAPS-1) of coeff_t;
  subtype delay_line_t is data_vec_t(0 to C_TAPS-1);

  constant C_COEFFS : coeff_vec_t := (
    to_signed(-118, C_COEFF_WIDTH),
    to_signed(0,    C_COEFF_WIDTH),
    to_signed(2213, C_COEFF_WIDTH),
    to_signed(6097, C_COEFF_WIDTH),
    to_signed(6097, C_COEFF_WIDTH),
    to_signed(2213, C_COEFF_WIDTH),
    to_signed(0,    C_COEFF_WIDTH),
    to_signed(-118, C_COEFF_WIDTH)
  );

end package fir_tb_pkg;
